  "code": "function mergeRanges(ranges) {
    if (!Array.isArray(ranges)) throw new TypeError('Input must be an array');

    const valid = [];
    for (const r of ranges) {
      if (!Array.isArray(r) || r.length !== 2) {
        throw new TypeError('Each range must be an array of length 2');
      }
      const [start, end] = r;
      if (typeof start !== 'number' || typeof end !== 'number') {
        throw new TypeError('Range values must be numbers');
      }
      if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) {
        throw new TypeError('Range values must be safe integers');
      }
      if (start >= end) {
        continue;
      }
      valid.push([start, end]);
    }

    valid.sort((a, b) => a[0] - b[0]);

    const merged = [];
    for (const r of valid) {
      const [start, end] = r;
      if (merged.length === 0) {
        merged.push([start, end]);
      } else {
        const last = merged[merged.length - 1];
        // Merge only if overlapping: current start < last end
        // Do NOT merge if merely touching: current start >= last end
        if (start < last[1]) {
          last[1] = Math.max(last[1], end);
        } else {
          merged.push([start, end]);
        }
      }
    }

    return merged;
